<script setup lang="ts">import { onMounted, ref } from "vue"; import { closeCashRegister, getCashRegister, openCashRegister, type CashRegister } from "../api"; const date = new Date().toISOString().slice(0, 10); const register = ref<CashRegister | null>(null); const error = ref(""); const money = (value: number) => new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR" }).format(value / 100); async function load() { try { register.value = await getCashRegister(date); } catch { register.value = null; } } async function open() { try { register.value = await openCashRegister(date); } catch (reason) { error.value = (reason as Error).message; } } async function close() { try { register.value = await closeCashRegister(date); } catch (reason) { error.value = (reason as Error).message; } } onMounted(load);</script><template><section><header><div><p class="eyebrow">TPV</p><h1>Caja diaria</h1></div></header><section class="detail-tab"><p v-if="error" class="feedback error">{{ error }}</p><h2>{{ register ? register.status === 'open' ? 'Caja abierta' : 'Caja cerrada' : 'Sin apertura' }}</h2><p>Fecha: {{ date }}</p><dl v-if="register"><dt>Cobrado</dt><dd>{{ money(register.paidCents) }}</dd><dt>Reembolsado</dt><dd>{{ money(register.refundedCents) }}</dd><dt>Neto</dt><dd>{{ money(register.netCents) }}</dd></dl><button v-if="!register" @click="open">Abrir caja</button><button v-else-if="register.status === 'open'" @click="close">Cerrar caja</button></section></section></template>